INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine einfache Python-Umgebung immer mitgeliefert wird?', 2, '[{"text": "Ja", "correct": true, "because": "Teil der Standardinstallation"}, {"text": "Nein", "correct": false, "because": "Kommt mit Python"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature hilft mir, Code direkt in einer Umgebung zu testen?', 3, '[{"text": "Shell-Fenster", "correct": true, "because": "Interaktive Ausführung"}, {"text": "Compiler", "correct": false, "because": "Nicht enthalten"}, {"text": "Browser", "correct": false, "because": "Kein Webtool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bietet eine Python-Entwicklungsumgebung?', 5, '[{"text": "Code-Editor", "correct": true, "because": "Zum Schreiben"}, {"text": "Interaktive Shell", "correct": true, "because": "Zum Testen"}, {"text": "Syntaxhervorhebung", "correct": true, "because": "Verbessert Lesbarkeit"}, {"text": "Datenbankverwaltung", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es unterstützt Debugging. b) Es ist für große Projekte ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist auf einfache Projekte ausgelegt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Umgebung für Python einrichte?', 4, '[{"text": "Code-Vervollständigung", "correct": false, "because": "Hilft beim Programmieren"}, {"text": "Debugging-Tools", "correct": false, "because": "Fehlerfindung"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass es nur für Profis geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Anfänger"}, {"text": "Ja", "correct": false, "because": "Einfach zu nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug wähle ich, um Python-Code interaktiv zu testen?', 3, '[{"text": "Shell", "correct": true, "because": "Direkte Eingabe möglich"}, {"text": "Editor", "correct": false, "because": "Nur Schreiben"}, {"text": "Terminal", "correct": false, "because": "Externer Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine einfache Entwicklungsumgebung?', 5, '[{"text": "Einfachheit", "correct": true, "because": "Schnell zu lernen"}, {"text": "Syntaxhervorhebung", "correct": true, "because": "Erleichtert Codierung"}, {"text": "Debugging", "correct": true, "because": "Fehler finden"}, {"text": "Cloud-Integration", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) es mit Python installiert wird und b) es für Java geeignet ist. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Python-spezifisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um in einer Umgebung zu programmieren?', 4, '[{"text": "Texteditor", "correct": false, "because": "Zum Schreiben nötig"}, {"text": "Shell", "correct": false, "because": "Für Tests hilfreich"}, {"text": "Grafikdesign-Tool", "correct": true, "because": "Kein Programmierfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist es für komplexe Projekte gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Eher für einfache Aufgaben"}, {"text": "Ja", "correct": false, "because": "Einfach gehalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen helfen beim Debuggen?', 4, '[{"text": "Breakpoints", "correct": true, "because": "Stoppen Ausführung"}, {"text": "Variableninspektion", "correct": true, "because": "Zeigt Werte"}, {"text": "Farbauswahl", "correct": false, "because": "Kein Debug-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass es nur für Windows ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Plattformübergreifend"}, {"text": "Ja", "correct": false, "because": "Läuft auf allen Systemen"}]'),
